package server

import (
	"log"
	"sync"
	"time"
)

// Private keys generated by the server (for phones / wg-quick / routers that
// cannot make their own) are never written to state.json or backups. They
// live only in this in-memory vault so the user can scan the QR code or
// download the .conf once, and are dropped as soon as the peer completes its
// first handshake, after keyRevealTTL, or on restart — whichever comes first.
// After that the config shows <YOUR-PRIVATE-KEY>; "Rotate keys" issues a new
// one-time config.
//
// Clients that generate their own key pair (the wg2fa desktop client, or a
// public key pasted when adding a device) never hand a private key to the
// server at all, which is the preferred path.

const keyRevealTTL = 15 * time.Minute

type revealKey struct {
	priv    string
	pub     string
	expires time.Time
}

type keyVault struct {
	mu sync.Mutex
	m  map[string]revealKey // peer ID -> key
}

func newKeyVault() *keyVault { return &keyVault{m: map[string]revealKey{}} }

func (v *keyVault) put(peerID, priv, pub string) {
	v.mu.Lock()
	defer v.mu.Unlock()
	v.m[peerID] = revealKey{priv: priv, pub: pub, expires: time.Now().Add(keyRevealTTL)}
}

// get returns the private key for peerID if it is still revealable and still
// belongs to the peer's current public key.
func (v *keyVault) get(peerID, pub string) string {
	v.mu.Lock()
	defer v.mu.Unlock()
	k, ok := v.m[peerID]
	if !ok {
		return ""
	}
	if time.Now().After(k.expires) || k.pub != pub {
		delete(v.m, peerID)
		return ""
	}
	return k.priv
}

func (v *keyVault) drop(peerID string) {
	v.mu.Lock()
	defer v.mu.Unlock()
	delete(v.m, peerID)
}

// sweep forgets expired keys and keys whose peer has already handshaked
// (the config was imported, so the server has no reason to hold the key).
func (v *keyVault) sweep(handshaked func(pub string) bool) {
	v.mu.Lock()
	defer v.mu.Unlock()
	now := time.Now()
	for id, k := range v.m {
		if now.After(k.expires) || handshaked(k.pub) {
			delete(v.m, id)
		}
	}
}

// scrubStoredPrivateKeys removes client private keys persisted by older
// versions. Affected users rotate keys (or re-import) to get a new config.
func scrubStoredPrivateKeys(st *state) int {
	n := 0
	for _, p := range st.Peers {
		if p.PrivateKey != "" {
			p.PrivateKey = ""
			n++
		}
	}
	if n > 0 {
		st.audit("system", "keys.scrubbed", "removed stored client private keys", "")
		log.Printf("security: removed %d client private key(s) from state; rotate keys on those devices to get a new config", n)
	}
	return n
}
